using Corvus.Json;
using Corvus.Json.CodeGeneration;
using Corvus.Text.Json.CodeGeneration;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Corvus.Text.Json.CodeGenerator.Tests;

/// <summary>
/// Every generated file starts with the single-line <c>// &lt;auto-generated/&gt;</c> header that Roslyn's own generators
/// use, followed by exactly what came after the old eight-line block.
/// </summary>
[TestClass]
public class AutoGeneratedHeaderTests
{
    // A oneOf gives a union, so the [Union] attribute polyfill file is emitted too.
    private const string Schema =
        """
        {
          "$schema": "https://json-schema.org/draft/2020-12/schema",
          "title": "Shape",
          "oneOf": [
            { "type": "object", "properties": { "radius": { "type": "number" } }, "required": ["radius"] },
            { "type": "object", "properties": { "side": { "type": "number" } }, "required": ["side"] }
          ]
        }
        """;

    [TestMethod]
    [DataRow("\r\n")]
    [DataRow("\n")]
    public async Task GenerateCode_EveryFile_StartsWithTheSingleLineAutoGeneratedHeader(string lineEnd)
    {
        IReadOnlyCollection<GeneratedCodeFile> files = await GenerateTypesAndEvaluator(lineEnd);

        string header = "// <auto-generated/>" + lineEnd;
        string[] kinds = ["type partial", "program", "standalone evaluator", "union attribute polyfill"];
        int[] seen = new int[kinds.Length];
        foreach (GeneratedCodeFile file in files)
        {
            int kind;
            string expected;
            if (file.FileName.StartsWith(Formatting.UnionAttributeFileName, StringComparison.Ordinal))
            {
                kind = 3;
                expected = header + lineEnd + "#if !NET11_0_OR_GREATER && !CORVUS_TEXT_JSON_NO_UNION_ATTRIBUTE_POLYFILL" + lineEnd;
            }
            else if (file.FileName.StartsWith("CorvusJsonSchemaProgram", StringComparison.Ordinal))
            {
                kind = 1;
                expected = header + "#nullable enable" + lineEnd + "#pragma warning disable" + lineEnd;
            }
            else if (file.FileName.EndsWith("Evaluator.cs", StringComparison.Ordinal))
            {
                kind = 2;
                expected = header + "#nullable enable" + lineEnd + "#pragma warning disable" + lineEnd;
            }
            else
            {
                kind = 0;
                expected = header + lineEnd + "#nullable enable" + lineEnd;
            }

            seen[kind]++;
            Assert.IsTrue(
                file.FileContent.StartsWith(expected, StringComparison.Ordinal),
                $"{file.FileName} ({kinds[kind]}) starts with:{Environment.NewLine}{file.FileContent[..Math.Min(200, file.FileContent.Length)]}");
            Assert.IsFalse(file.FileContent.Contains("This code was generated by a tool", StringComparison.Ordinal), file.FileName);
        }

        for (int i = 0; i < kinds.Length; i++)
        {
            Assert.IsTrue(seen[i] > 0, $"no {kinds[i]} file was generated: {string.Join(", ", files.Select(f => f.FileName))}");
        }
    }

    // Types and the standalone evaluator together (mode Both), which needs the evaluator root types set on the
    // provider; the shared in-process helper generates types only.
    private static async Task<IReadOnlyCollection<GeneratedCodeFile>> GenerateTypesAndEvaluator(string lineEnd)
    {
        string directory = Directory.CreateTempSubdirectory("auto-generated-header-").FullName;
        try
        {
            string schemaFile = Path.Combine(directory, "shape.json");
            await File.WriteAllTextAsync(schemaFile, Schema);

            CompoundDocumentResolver documentResolver = new(new FileSystemDocumentResolver(), new HttpClientDocumentResolver(new HttpClient()));
            VocabularyRegistry vocabularyRegistry = new();
            Corvus.Json.CodeGeneration.Draft202012.VocabularyAnalyser.RegisterAnalyser(documentResolver, vocabularyRegistry);
            JsonSchemaTypeBuilder typeBuilder = new(documentResolver, vocabularyRegistry);
            TypeDeclaration rootType = await typeBuilder.AddTypeDeclarationsAsync(
                new JsonReference(schemaFile),
                Corvus.Json.CodeGeneration.Draft202012.VocabularyAnalyser.DefaultVocabulary);

            CSharpLanguageProvider languageProvider = CSharpLanguageProvider.DefaultWithOptions(
                new CSharpLanguageProvider.Options(defaultNamespace: "Test", lineEndSequence: lineEnd, codeGenerationMode: CodeGenerationMode.Both));
            languageProvider.SetEvaluatorRootTypes(rootType);
            return typeBuilder.GenerateCodeUsing(languageProvider, [rootType], CancellationToken.None);
        }
        finally
        {
            Directory.Delete(directory, true);
        }
    }
}